alter table public.picture_caption_rounds drop constraint picture_caption_rounds_phase_check;
alter table public.picture_caption_rounds add constraint picture_caption_rounds_phase_check check(phase is null or phase in ('captioning','voting','revealing','results'));
create table public.picture_caption_reveals(round_id uuid primary key references public.picture_caption_rounds(id) on delete restrict,started_at timestamptz not null default now(),paused_at timestamptz,unique(round_id));
alter table public.picture_caption_reveals enable row level security;
revoke all on table public.picture_caption_reveals from public,anon,authenticated;

create function public.start_picture_caption_reveal(p_host_id uuid,p_party_id uuid,p_command_id uuid,p_expected_revision bigint) returns table(game_session_id uuid,session_revision bigint) language plpgsql security definer set search_path='' as $$ declare existing jsonb; session_record public.game_sessions; round_record public.picture_caption_rounds; next_revision bigint; begin select response into existing from public.command_receipts where actor_id=p_host_id and command_id=p_command_id; if found then return query select(existing->>'gameSessionId')::uuid,(existing->>'sessionRevision')::bigint; return; end if; select session.* into session_record from public.parties party join public.game_sessions session on session.id=party.current_game_session_id where party.host_id=p_host_id and party.id=p_party_id and session.revision=p_expected_revision for update of session; if not found then raise exception using errcode='40001',message='stale_revision'; end if; select round.* into round_record from public.picture_caption_rounds round join public.picture_caption_round_results result on result.round_id=round.id where round.game_session_id=session_record.id and round.state='completed' order by round.position desc limit 1 for update of round; if not found then raise exception using errcode='40001',message='result_unavailable'; end if; insert into public.picture_caption_reveals(round_id) values(round_record.id); update public.picture_caption_rounds set state='active',phase='revealing' where id=round_record.id; update public.game_sessions set revision=revision+1 where id=session_record.id returning revision into next_revision; insert into public.command_receipts values(p_host_id,p_command_id,'start_picture_caption_reveal',jsonb_build_object('gameSessionId',session_record.id,'sessionRevision',next_revision)); return query select session_record.id,next_revision; exception when unique_violation then raise exception using errcode='40001',message='reveal_already_started'; end; $$;

create function public.continue_picture_caption_round(p_host_id uuid,p_party_id uuid,p_command_id uuid,p_expected_revision bigint) returns table(game_session_id uuid,session_revision bigint) language plpgsql security definer set search_path='' as $$ declare existing jsonb; session_record public.game_sessions; active_round public.picture_caption_rounds; next_revision bigint; begin select response into existing from public.command_receipts where actor_id=p_host_id and command_id=p_command_id; if found then return query select(existing->>'gameSessionId')::uuid,(existing->>'sessionRevision')::bigint; return; end if; select session.* into session_record from public.parties party join public.game_sessions session on session.id=party.current_game_session_id where party.host_id=p_host_id and party.id=p_party_id and session.revision=p_expected_revision for update of session; if not found then raise exception using errcode='40001',message='stale_revision'; end if; select round.* into active_round from public.picture_caption_rounds round where round.game_session_id=session_record.id and round.state='active' and round.phase in ('revealing','results') for update; if not found then raise exception using errcode='40001',message='result_unavailable'; end if; update public.picture_caption_rounds set state='completed',phase=null where id=active_round.id; update public.game_sessions set revision=revision+1 where id=session_record.id returning revision into next_revision; insert into public.command_receipts values(p_host_id,p_command_id,'continue_picture_caption_round',jsonb_build_object('gameSessionId',session_record.id,'sessionRevision',next_revision)); return query select session_record.id,next_revision; end; $$;
revoke all on function public.start_picture_caption_reveal(uuid,uuid,uuid,bigint),public.continue_picture_caption_round(uuid,uuid,uuid,bigint) from public,anon,authenticated;
grant execute on function public.start_picture_caption_reveal(uuid,uuid,uuid,bigint),public.continue_picture_caption_round(uuid,uuid,uuid,bigint) to service_role;